import {execFileSync} from 'node:child_process';
import process from 'node:process';

describe('Validation logging contract [specs/hal-engine-tool-input-validation/spec.md#4]', () => {
  it('logs the rejected ssn path and type without its value', () => {
    const output = execFileSync(
      process.execPath,
      [
        '--import',
        'tsx',
        '--input-type=module',
        '-e',
        "'`import {ToolRegistry} from '"'./src/orchestration/tools/registry.ts';
