        registry.register({
          name: 'lookup', description: 'Lookup by identifier',
          inputSchema: {type: 'object', properties: {ssn: {type: 'string'}}}
        }, async input => JSON.stringify(input));
        const response = await registry.execute('lookup', {ssn: 123456789});
        process.stdout.write(JSON.stringify(response) + '\\\\n');"'`,
      ],
      {encoding: '"'utf8', timeout: 10000, env: {...process.env, LOG_LEVEL: 'WARN'}}
    );
    const lines = output.trim().split('\\n');

    expect({
      warning: lines.find(line => line.includes('\"severity\":\"WARN\"')),
      response: lines.at(-1),
      leaksValue: output.includes('123456789'),
    }).toEqual({
      warning: expect.stringMatching(/ssn.*string/),
      response: expect.stringMatching(/ssn.*string/),
      leaksValue: false,
    });
  });
});
EOF
